insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p51', 'allemand', '3AS', 12, 51, 'L3 3AS p51 — Synonyme · Gegenteile · 3 Fragen · Übersetzen · heit/keit (Der technische Fortschritt)', E'3. Ersetzen Sie die unterstrichenen Wörter durch Wörter aus dem Text.\n- Man kann heutzutage menschliche Organe transplantieren.\n- Viele Krankheiten können dank der Fortschritte bekämpft werden.\n- Satelliten werden auf andere Planeten geschickt.\n- Der technische Fortschritt gibt dem Menschen die Möglichkeit, besser zu leben.\n- Der Mensch kann ohne Sorgen leben.\n4. Suchen Sie die Gegenteile von den hier unterstrichenen Wörtern.\n- Der ökonomische Rückschritt hat gravierende Folgen.\n- Der Mensch kümmert sich um seine Gesundheit.\n- Die Wissenschaftler haben eine überlegte Entscheidung getroffen.\n- Der Mensch schützt seine Natur.\n5. Antworten Sie.\n1. Wozu dient der technische Fortschritt ?\n2. Was ermöglicht der technische Fortschritt ?\n3. Inwiefern hat der technische Fortschritt negative Konsequenzen ?\n6. Übersetzen Sie ins Arabische.\n- Der technische Fortschritt bietet den Menschen unglaublich große Möglichkeiten.\n7. heit oder keit ?\nkrank · höflich · ängstlich · bequemlich · freundlich · berühmt · zufrieden · wichtig · natürlich · möglich · schön · sicher · gesund · verrückt · traurig · feindlich\n- sicher + heit → die Sicherheit\n- bequemlich + keit → die Bequemlichkeit', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p52', 'allemand', '3AS', 12, 52, 'L3 3AS p52 — um…zu + Infinitiv : Computer, eine technische Revolution, um besser zu leben', E'Computer - eine technische Revolution, um besser zu leben.\n1. Üben Sie zu zweit wie im Beispiel.\n- Wozu haben die Wissenschaftler den Computer erfunden ?\n- Sie haben den Computer erfunden, um unser Leben zu erleichtern.\n- Wozu benutzen wir den Computer ?\n- Wozu brauchst du ein neues Handy ?\n- Wozu kaufst du eine Satellitenantenne ?\n- Wozu benützt du einen Taschenrechner ?\n- Wozu haben Sie ein Faxgerät ?\num…zu + Infinitiv\nTabelle : Arbeitszeit verkürzen · bequemer telefonieren · mehr Fernsehprogramme sehen · schneller addieren · Nachrichten sicher versenden\n2. Bilden Sie Sätze mit «um ... zu».\n- Die Unternehmer benutzen neue Maschinen. Sie wollen die Produktion erhöhen.\n- Die Wissenschaftler trafen sich. Sie diskutierten über den technischen Fortschritt.\n- Er gibt seinen Beruf auf. Er will in die Politik gehen.\n- Die Ärzte haben das Antibiotikum erfunden. Sie wollen gegen die Bakterien kämpfen.\n- Die Fabrikbesitzer entscheiden sich lieber für die Maschinen. Sie wollen mehr gewinnen.\n3. Üben Sie zu zweit wie im Beispiel.\n- Wozu brauchst du einen neuen Computer ?\n- Ich brauche einen neuen Computer, damit mein Leben leichter wird.\n- Wozu benutzen wir den Computer ?\n- Wozu brauchst du ein neues Handy ?\n- Wozu kaufst du eine Satellitenantenne ?\n- Wozu benützt du einen Taschenrechner ?\n…, damit …. Verb (konjugiert)\nTabelle : Arbeitszeit verkürzen (können) · bequemer telefonieren (können) · mehr Fernsehprogramme sehen (können) · schneller addieren (können)', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p53', 'allemand', '3AS', 12, 53, 'L3 3AS p53 — damit-Sätze verbinden + Ergänzen + Der Computer (Bildschirm · Tastatur · Rechner · Maus · Mousepad)', E'4. Verbinden Sie die Sätze mit «damit».\n- Eine neue Maschine kommt auf den Markt. Die Produktion kann schneller werden.\n- Thomas Edison hat die Glühbirne erfunden. Das Licht wurde heller.\n- Daimler und Benz haben das Automobil entwickelt. Die Leute konnten schneller reisen.\n- Neue Medikamente werden verkauft. Menschenleben können gerettet werden.\n- Mein Vater hat mir ein Handy geschenkt. Ich kann bequemer telefonieren.\n5. Ergänzen Sie.\n- Die Wissenschaftler haben neue Geräte hergestellt, …..\n- Man hat das Handy erfunden, …..\n- Wir brauchen neue Maschinen, ……..\n- Der Arzt gibt dem Patienten Medikamente, ……\n- Sie bilden eine Arbeitsgruppe, ……\nFoto : Der Computer — Der Bildschirm · Die Tastatur · Der Rechner · Die Maus · Das Mousepad', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p54', 'allemand', '3AS', 12, 54, 'L3 3AS p54 — 3 Meinungen : Lina Meyer (27) · Arthur Schwarze (19) · Hilde Zander (50) + R/F', E'Computer, eine technische Revolution\nLina Meyer, 27 Jahre :\nIch habe Angst vor einer Welt, die von Computern geregelt wird. Wir sollten die Entwicklung stoppen, ehe es zu spät ist. Während der Mensch anfangs die Maschinen programmiert hat, um besser leben zu können, programmieren jetzt die Maschinen den Menschen. Sie sagen ihm, was er tun soll. Wir dürfen nicht mehr entscheiden, der Computer übernimmt alle Entscheidungen. Sind wir dann überhaupt noch richtige Menschen ?\n1. Richtig oder falsch ? Kreuzen Sie an.\n- Der Computer beherrscht den Menschen.\n- Der Computer wird durch den Menschen ersetzt.\n- Er beeinflusst den Menschen in seinem Leben.\nArthur Schwarze, 19 Jahre :\nSeitdem es Computer gibt, wächst die Hoffnung, dass die Maschinen eines Tages dem Menschen den größten Teil harter Arbeit abnehmen werden. Wir brauchen dann keine endlosen Zahlenreihen mehr zusammenzuzählen.\nDer Computer kann alle Daten speichern. Alle anstrengenden und langweiligen Arbeiten werden Maschinen machen, denen Computer sagen, was sie tun sollen.\n2. Richtig oder falsch ? Kreuzen Sie an.\n- Der Computer ist eine Gefahr für die Menschen.\n- Er kompliziert die Arbeit des Menschen.\n- Der Mensch arbeitet weniger.\nHilde Zander, 50 Jahre :\nDie neue Technik dient leider nicht den Interessen der Arbeitnehmer. Sobald sich ein Unternehmer für Computer entscheidet, braucht er weniger Arbeitskräfte und kann dadurch seine Gewinne erhöhen. Erstens : Computer sind billiger als Arbeitskräfte und brauchen keine Arbeitsverträge. Zweitens : Sie sind gehorsamer, denn sie widersprechen nie. Drittens : Computer sind leichter zu kontrollieren und zuverlässiger als Menschen.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p55', 'allemand', '3AS', 12, 55, 'L3 3AS p55 — Computer : R/F (3) · Synonyme · Gegenteile · 3 Fragen · Übersetzen', E'3. Richtig oder falsch ? Kreuzen Sie an.\n- Der Computer bedroht die Arbeitnehmer.\n- Für die Unternehmer ist der Computer eine Gefahr.\n- «Mehr Computer bedeutet» weniger Arbeitsplätze.\n4. Ersetzen Sie die hier unterstrichenen Wörter durch gleichbedeutende Wörter aus dem Text.\n- Der Computer organisiert unser Leben.\n- Bevor er zur Arbeit geht, konsultiert er seinen Computer.\n- Die Zahl der Arbeitslosen nimmt ständig zu.\n- Der Computer bewahrt alle Informationen auf.\n- Die Maschinen werden schwere Arbeiten machen.\n5. Suchen Sie die Gegenteile von den hier unterstrichenen Wörtern.\n- Früher war die Arbeit hart, heute ist sie dank dem Computer ………\n- «Weniger Arbeitsplätze» bedeutet mehr Gewinn für die Unternehmer, das ist aber ein ……… für die Arbeitnehmer.\n- Früher arbeiteten die Bauern viel, aber heute dank dem technischen Fortschritt arbeiten sie ………\n6. Antworten Sie.\n1. Warum hält Lina den Computer für eine Gefahr ?\n2. Weshalb ist für Arthur der Computer eine positive Erfindung ?\n3. Welche negative Folgen hat der Computer nach Hildes Meinung ?\n7. Übersetzen Sie ins Arabische.\nDer Mensch hat anfangs die Maschinen programmiert, um besser zu leben.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
